import sys

def k_smallest_pairs_brute(nums1, nums2, k):
    pairs = []
    for i, a in enumerate(nums1):
        for j, b in enumerate(nums2):
            pairs.append((a + b, a, b, i, j))
    pairs.sort(key=lambda t: (t[0], t[3], t[4]))
    return [(a, b) for _, a, b, _, _ in pairs[:k]]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    nums1 = list(map(int, data[2:2 + m]))
    nums2 = list(map(int, data[2 + m:2 + m + n]))
    k = int(data[2 + m + n])
    for a, b in k_smallest_pairs_brute(nums1, nums2, k):
        print(a, b)

import sys
import heapq

def k_smallest_pairs_best(nums1, nums2, k):
    m, n = len(nums1), len(nums2)
    if not m or not n:
        return []
    seen = {(0, 0)}
    heap = [(nums1[0] + nums2[0], 0, 0)]
    res = []
    while heap and len(res) < k:
        _, i, j = heapq.heappop(heap)
        res.append((nums1[i], nums2[j]))
        if i + 1 < m and (i + 1, j) not in seen:
            seen.add((i + 1, j))
            heapq.heappush(heap, (nums1[i + 1] + nums2[j], i + 1, j))
        if j + 1 < n and (i, j + 1) not in seen:
            seen.add((i, j + 1))
            heapq.heappush(heap, (nums1[i] + nums2[j + 1], i, j + 1))
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    nums1 = list(map(int, data[2:2 + m]))
    nums2 = list(map(int, data[2 + m:2 + m + n]))
    k = int(data[2 + m + n])
    for a, b in k_smallest_pairs_best(nums1, nums2, k):
        print(a, b)
